package formats

import (
	"context"
	"fmt"
	"strings"
	"time"

	"github.com/openartifact/openartifact/internal/database/models"
	"github.com/openartifact/openartifact/internal/format/lifecycle"
)

// The metadata lifecycles. A format whose indexes are generated by a worker
// (rpm, deb, pacman, apk repository indexes, maven-metadata.xml, the npm
// packument) says here how to refresh them; every other format computes its
// indexes live from the tables (cargo index, conan, conda repodata, go, helm
// index.yaml, ivy, nuget, pypi simple, raw, rubygems specs, sbt, terraform) and
// has lifecycle.None.

// markTimeout bounds the write of a stale flag.
const markTimeout = 15 * time.Second

// repoNotifier is the metadata worker of a format that regenerates the whole
// index of a repository (*worker.DebMetadataWorker and friends).
type repoNotifier interface{ NotifyStale(repoID string) }

// notifyRepo schedules the regeneration of a repository's indexes. When mark is
// set the repository is flagged stale in the database first, so the stale sweep
// recovers the refresh if the notification is lost or the process dies (rpm).
// The worker is notified even when the flag could not be set.
func notifyRepo(format string, mark bool) func(ctx context.Context, env *lifecycle.Env, repoID string) error {
	return func(ctx context.Context, env *lifecycle.Env, repoID string) error {
		var err error

		if mark && env.MarkRepoStale != nil {
			// The flag must land even when the request or run that caused the
			// refresh is already cancelled.
			mctx, cancel := context.WithTimeout(context.WithoutCancel(ctx), markTimeout)
			defer cancel()

			if markErr := env.MarkRepoStale(mctx, repoID); markErr != nil {
				err = fmt.Errorf("mark %s repository stale: %w", format, markErr)
			}
		}

		if n, ok := lifecycle.Worker[repoNotifier](env.Workers, format); ok {
			n.NotifyStale(repoID)
		}

		return err
	}
}

// repoLifecycle is the lifecycle of a format with one generated index per
// repository: every event refreshes that index.
func repoLifecycle(format string, mark bool) lifecycle.Hooks {
	stale := notifyRepo(format, mark)

	refresh := func(ctx context.Context, env *lifecycle.Env, repoID, event string) {
		if err := stale(ctx, env, repoID); err != nil {
			env.Log.Warnw(event+": metadata refresh failed", "repository_id", repoID, "format", format, "error", err)
		}
	}

	return lifecycle.Hooks{
		Stale: stale,
		Removed: func(ctx context.Context, env *lifecycle.Env, r lifecycle.Removal) {
			refresh(ctx, env, r.Repo.ID, "cleanup")
		},
		Restored: func(ctx context.Context, env *lifecycle.Env, r lifecycle.Restoration) {
			refresh(ctx, env, r.RepositoryID, "trash restore")
		},
	}
}

// mavenNotifier is *worker.MavenMetadataWorker: it regenerates the
// maven-metadata.xml files of one artifact.
type mavenNotifier interface {
	NotifyStale(repoID, groupID, artifactID string)
}

// mavenLifecycle refreshes the metadata files of the artifacts that changed:
// all of a repository's when it is rebuilt, the ones a cleanup run or a restore
// touched otherwise.
func mavenLifecycle() lifecycle.Hooks {
	return lifecycle.Hooks{
		Stale: func(ctx context.Context, env *lifecycle.Env, repoID string) error {
			n, ok := lifecycle.Worker[mavenNotifier](env.Workers, "maven")
			if !ok || env.SQL == nil {
				return nil
			}

			// The package is one group:artifact, whose coordinates the store keeps in attrs.
			rows, err := env.SQL.QueryContext(ctx,
				`SELECT DISTINCT p.attrs->>'group_id', p.attrs->>'artifact_id'
				   FROM packages p
				   JOIN package_versions v ON v.package_id = p.id AND v.deleted_at IS NULL
				  WHERE p.repository_id = $1 AND p.format = 'maven'`, repoID)
			if err != nil {
				return fmt.Errorf("list maven artifacts: %w", err)
			}

			defer func() { _ = rows.Close() }()

			for rows.Next() {
				var group, artifact string
				if err := rows.Scan(&group, &artifact); err != nil {
					return fmt.Errorf("scan maven artifact: %w", err)
				}

				n.NotifyStale(repoID, group, artifact)
			}

			return rows.Err() //nolint:wrapcheck // iteration error
		},
		// Removed regenerates the version list and the snapshot metadata of
		// every artifact a run removed files of, so clients stop resolving
		// removed versions and builds.
		Removed: func(_ context.Context, env *lifecycle.Env, r lifecycle.Removal) {
			n, ok := lifecycle.Worker[mavenNotifier](env.Workers, "maven")
			if !ok {
				return
			}

			for _, name := range r.Names {
				group, artifact, found := strings.Cut(name, ":")
				if found {
					n.NotifyStale(r.Repo.ID, group, artifact)
				}
			}
		},
		Restored: func(ctx context.Context, env *lifecycle.Env, r lifecycle.Restoration) {
			n, ok := lifecycle.Worker[mavenNotifier](env.Workers, "maven")
			if !ok || r.RegenKeys == nil {
				return
			}

			group, artifact, err := r.RegenKeys(ctx)
			if err != nil {
				env.Log.Warnw("trash restore: resolve regeneration keys failed",
					"repository", r.RepositoryName, "kind", r.Kind, "error", err)
				return
			}

			n.NotifyStale(r.RepositoryID, group, artifact)
		},
	}
}

// packumentNotifier is *worker.NPMMetadataWorker: it regenerates one package's
// denormalized packument fields (latest version).
type packumentNotifier interface{ NotifyStale(packageID string) }

// npmLifecycle keeps the packuments in step with the versions of their packages.
func npmLifecycle() lifecycle.Hooks {
	return lifecycle.Hooks{
		// Removed drops the package that lost its last version row; the others
		// get a new packument validator and a regeneration of the latest version.
		// Versions a dist-tag points at are never removed, so no dist-tag is left
		// dangling.
		Removed: func(ctx context.Context, env *lifecycle.Env, r lifecycle.Removal) {
			if env.SQL == nil {
				return
			}

			for _, name := range r.Names {
				var pkgID string

				err := env.SQL.QueryRowContext(ctx,
					`SELECT id::text FROM packages WHERE repository_id = $1 AND format = 'npm' AND name_key = $2`,
					r.Repo.ID, name).Scan(&pkgID)
				if err != nil {
					env.Log.Warnw("cleanup: failed to resolve npm package", "repository_id", r.Repo.ID, "package", name, "error", err)
					continue
				}

				res, err := env.SQL.ExecContext(ctx,
					`DELETE FROM packages p WHERE p.id = $1::uuid
					   AND NOT EXISTS (SELECT 1 FROM package_versions v WHERE v.package_id = p.id)`, pkgID)
				if err == nil {
					if rows, _ := res.RowsAffected(); rows > 0 {
						continue
					}
				}

				markAndNotifyPackument(ctx, env, r.Repo.Name, pkgID, "cleanup")
			}
		},
		Restored: func(ctx context.Context, env *lifecycle.Env, r lifecycle.Restoration) {
			if r.RegenKeys == nil {
				return
			}

			packageID, _, err := r.RegenKeys(ctx)
			if err != nil {
				env.Log.Warnw("trash restore: resolve regeneration keys failed",
					"repository", r.RepositoryName, "kind", r.Kind, "error", err)
				return
			}

			markAndNotifyPackument(ctx, env, r.RepositoryName, packageID, "trash restore")
		},
	}
}

// markAndNotifyPackument flips the packument's stale marker first, so its ETag
// changes at once, then schedules the regeneration.
func markAndNotifyPackument(ctx context.Context, env *lifecycle.Env, repo, packageID, event string) {
	if env.MarkPackumentStale != nil {
		if err := env.MarkPackumentStale(ctx, packageID); err != nil {
			env.Log.Warnw(event+": failed to mark packument stale", "repository", repo, "package_id", packageID, "error", err)
		}
	}

	if n, ok := lifecycle.Worker[packumentNotifier](env.Workers, "npm"); ok {
		n.NotifyStale(packageID)
	}
}

// registryCollector is *worker.DockerGCWorker.
type registryCollector interface {
	// CollectRemoved runs the registry garbage collection of a repository
	// after tags were deleted from it.
	CollectRemoved(ctx context.Context, repo *models.Repository) error
}

// dockerLifecycle runs registry garbage collection after tags were deleted for
// good: the manifests only they tagged and the layers only those referenced are
// reclaimed (with the GC's own grace period). Tags moved to the trash change
// nothing for the GC until they are purged.
func dockerLifecycle() lifecycle.Hooks {
	return lifecycle.Hooks{
		Removed: func(ctx context.Context, env *lifecycle.Env, r lifecycle.Removal) {
			c, ok := lifecycle.Worker[registryCollector](env.Workers, "docker")
			if !ok || r.Hard == 0 {
				return
			}

			if err := c.CollectRemoved(ctx, r.Repo); err != nil {
				env.Log.Warnw("cleanup: docker garbage collection failed", "repository_id", r.Repo.ID, "error", err)
			}
		},
	}
}
